const en: Copy = {
  meta: { title: "CompanyONE | Your company. One system.", description: "CompanyONE brings your business together: an information system on your own infrastructure, customizable modules, and Agent One and Dev One as part of your team." },
  nav: ["Why", "Foundation", "System", "FAQ", "Team", "Customization", "In practice"], menu: "Menu", language: "Language", theme: "Switch color theme", skip: "Skip to content",
  hero: { intro: "Built around your business", title: ["Your company.", "One system."], body: "Your own computer. A system you can shape. Private agents on your team.", scene: "A 3D illustration of CompanyONE: a company-owned computer supports connected business modules, with Agent One and Dev One alongside them.", tabs: ["Your computer", "Your system", "Your team"], descriptions: ["The foundation is yours. CompanyONE runs on hardware your company controls.", "Start with connected modules. Bring your data. Make every workflow your own.", "Agent One does the work. Dev One evolves the system. Both work with your team."], pause: "Pause animation", play: "Play animation" },
  why: {"kicker": "Why CompanyONE", "title": "Your business has outgrown the workaround.", "body": "A customer lives in one app. The conversation is in another. The next step sits in a spreadsheet. Your team becomes the connection between them: copying records, chasing updates, and adapting its work to what each subscription allows.", "points": [["Bring the context together", "Connect customers, conversations, sales, work, and knowledge so the next task starts with the information already behind it."], ["Change the process when you need to", "A new service, a different approval step, a field your industry needs: your information system can evolve with the way you actually work."], ["Build on what belongs to your company", "Keep the installation and records on infrastructure you control. The workflows and capabilities you add become part of your company’s own system."]]},
  customization: {"kicker": "From a request to a capability", "title": "Describe the change. Make it part of your system.", "body": "Some improvements need more than a setting. Dev One can help modify the information system itself, so your company can extend its workflows without waiting for a vendor’s roadmap.", "request": "“Our events need a start date and an end date. The calendar should show the whole event.”", "steps": [["Define the outcome", "Explain what is getting in the way. Dev One helps clarify the need and the approach before changing the system."], ["Build around the existing work", "Extend the event record and calendar together, preserving the workflow the team already uses."], ["Test and review", "Review a tested change in the development preview before approving it for the company’s working system."], ["Keep building from there", "The improvement becomes part of CompanyONE. Future changes can build on the same records, modules, and business context."]], "control": "Your people remain in control. Permissions define access, and consequential agent actions and system changes are reviewed before approval."},
  hardware: { title: "It starts with something you own.", body: "CompanyONE is installed, hosted, and run on your company’s infrastructure, whether that means a computer at your office or a server with the cloud provider you choose.", points: [["Your choice of home", "On premises or in your own cloud environment. You decide where the system lives."], ["Backups, taken care of", "Your business data is backed up automatically."], ["A foundation that stays current", "The agents help keep CompanyONE updated and tailored to your company."]], label: "Company-owned infrastructure", installed: "CompanyONE installed", backup: "Automatic backups" },
  system: { kicker: "The information system", title: "Everything connects. Everything can change.", body: "The familiar tools of business software, with the freedom to make them yours. Customers, conversations, knowledge, and work share one connected foundation.", tabs: ["The whole picture", "Customer conversations", "Organized work"], descriptions: ["See what needs your attention across the company, in one place.", "Keep customer conversations connected to the people and work behind them.", "Turn the way your team works into boards, calendars, and repeatable processes."], caption: "Early product preview. Interface and capabilities continue to evolve.", alt: ["CompanyONE knowledge workspace displayed on a laptop", "CompanyONE shared inbox with customer conversations", "CompanyONE event calendar with multi-day events"], importTitle: "Bring the work you’ve already done.", importBody: "Start with your existing records. Import data from spreadsheets and other systems, then organize it around the way your company works.", sources: ["Spreadsheets", "Customer records", "Existing systems"], destination: "Your company’s context", importNote: "A useful starting point. Never a blank slate." },
  team: { kicker: "Meet your new teammates", title: "They don’t just answer. They help move the business forward.", body: "Agent One and Dev One are private agents embedded in CompanyONE, working with your company’s context and alongside your people.", agentRole: "Works in your business.", agentBody: "Ask for an outcome. Agent One uses the information system and connected tools to organize records, handle tasks, and bring the results back into your company’s work.", devRole: "Works on your system.", devBody: "Describe what needs to change. Dev One helps customize workflows, extend modules, and build new capabilities as your company evolves.", agentTasks: ["Understands the context", "Coordinates the work", "Keeps information connected"], devTasks: ["Customizes workflows", "Builds new capabilities", "Helps maintain the system"], note: "Your people set the direction. The agents work alongside them." },
  story: { title: "From a spreadsheet to a better way of working.", body: "One beta company attends events throughout the year. Its spreadsheet held the schedule, but travel bookings and team assignments needed a shared process. The team brought that existing work into CompanyONE and shaped the system around it.", request: "“Help us organize our events, travel bookings, and team assignments.”", steps: [["Bring in the existing work", "Agent One recommended a Kanban board and imported the existing events, so the team could start from its own records."], ["Make it fit the team", "A reusable event card brought hotel reservations, flights, and rental cars into one checklist. Labels made team assignments part of the same process."], ["Extend what’s possible", "The agent suggested an end-date field for multi-day events. That need became a system improvement, connecting the event’s dates with its calendar view."]], caption: "Event planning in CompanyONE. Example data shown." },
  modules: { title: "A solid start. An open future.", body: "Start with practical ERP and CRM modules. Add, adapt, and extend them as your business finds its own way of working.", items: [["Relationships", "Customers, companies, and their history."], ["Inbox", "Customer conversations in one place."], ["Pipeline", "Opportunities and the next steps."], ["Boards", "Projects, calendars, and repeatable work."], ["Knowledge", "The context that makes your company yours."], ["Workspaces", "Separate teams, brands, and business contexts."]], final: "These are starting points. Your business defines what comes next." },
  faq: {
    kicker: "Frequently asked questions", title: "What CompanyONE is—and what it isn’t.", intro: "Direct answers for small-business owners. Open any question for more detail your team, adviser, or software agent can use to evaluate CompanyONE.", expandAll: "Expand all", collapseAll: "Collapse all", label: "CompanyONE frequently asked questions",
    items: [
      ["What is CompanyONE?", "CompanyONE is a private, self-hosted operating system for running a small company.", "It brings customers, sales, conversations, work, and company knowledge into one connected information system. Agent One works with that shared context to help organize information and carry out work. When the company needs the system itself to change, Dev One can build and test new modules, workflows, and capabilities for human review."],
      ["Who is it for?", "It is business software you own, customize, extend, and put to work for your company.", "It is especially useful when important context is scattered across tools, the way the company works does not fit a generic template, or the owners want greater control over their system and data. If the business only needs one simple, standardized function, a conventional SaaS product may still be the easier choice."],
      ["What features are included?", "You get a business dashboard, shared customer inbox, CRM and sales pipeline, advertising management, project boards and calendars, a company knowledge base, multi-company workspaces, and Agent One.", "The dashboard shows the company’s operating picture. The shared inbox brings website chat, text, and email together. CRM and the sales pipeline organize contacts, activities, opportunities, and next steps. Advertising management connects Google and Meta performance with controlled actions. Project management provides boards, calendars, templates, checklists, and files. The knowledge base is the company’s source of truth, workspaces keep different companies separate, and Agent One works across this shared context. These features are starting points, not the system’s fixed boundary. Dev One can add modules, workflows, and capabilities as the company’s needs evolve."],
      ["Is it just another chatbot?", "No. Agent One works inside the same information system where the company’s work and knowledge live.", "A generic chatbot usually answers from a conversation and whatever someone pastes into it. Agent One can use the active company workspace, consult the company’s source of truth, work with authorized business records, prepare exact changes for approval, and link people back to the resulting work. It is part of the operating system, not a separate chat window with no connection to the business."],
      ["What isn’t it?", "It is not a one-size-fits-all SaaS, an empty no-code builder, or a system that takes important actions without you.", "It starts with useful business capabilities and is then shaped around the company. It is also not necessarily offline: connected email, text messaging, advertising, internet access, and agent providers still depend on their respective services. The system coordinates those tools while keeping the company’s core information system under its control."],
      ["Why choose it instead of regular SaaS?", "Choose it when adapting the system to the business matters more than adapting the business to the software.", "Regular SaaS is convenient for standardized needs, but multiple products can leave a company with separate subscriptions, duplicated data, and workflows set by different vendors. This system provides one connected foundation that the company controls and can extend. It is not based on the idea that every SaaS product is bad; it is for businesses that need more continuity, context, and adaptability than a collection of fixed tools can provide."],
      ["Can it replace our current software?", "Yes. If it cannot replace a tool today, it can grow to replace it—at the speed and in the direction your company chooses.", "Begin with the workflows that matter most. The system can absorb more functions over time, in the order the company prioritizes them. Agent One helps operate the business in the current system, while Dev One builds the next capabilities. The company’s priorities—not a fixed vendor roadmap—determine the sequence. External networks such as email delivery, text messaging, and advertising platforms may remain connected infrastructure even when their business workflows are managed inside your system."],
      ["What happens when our business changes?", "The system can change with it.", "A new need may be handled by adjusting a workflow, creating a template, adding a module, or extending the system. For deeper changes, Dev One can help turn the desired outcome into a tested system change. A person reviews that work before it reaches the live company system. The company does not have to wait for a generic vendor roadmap to recognize every specialized need."],
      ["Where does our data live?", "Your company controls the computer, database, files, and backups used by its installation.", "Your installation is self-hosted rather than placing every customer inside one shared vendor application. Each new installation uses a fresh database and credentials created for that business; release packages do not contain another company’s data, files, secrets, or backups. Connected providers still process the information required to deliver their services, so self-hosted does not mean that no outside service ever receives data."],
      ["Can Agent One take action without our approval?", "Important changes remain under human control.", "Agent One can read authorized information, explain what it found, and prepare work. Changes to company records and consequential external actions require explicit, scoped approval tied to the administrator, workspace, target, and requested values. User permissions and workspace boundaries provide additional limits on what each person or agent can access."],
      ["Do we need a technical team?", "No. Agent One and Dev One are your operations and engineering team.", "Agent One works alongside the owner to understand the company’s context, organize work, and carry out approved operational actions. Dev One builds, tests, maintains, and extends the system as the business changes. The owner sets the direction and approves consequential changes, while the agents handle the operational and technical work."],
      ["Can one installation support more than one company?", "Yes. One installation can manage multiple companies as separate workspaces.", "Each workspace keeps its own business records, files, branding, searches, knowledge, and operational context. Accounts and installation-wide administration are managed centrally. When Agent One works with company information, the active workspace determines which company’s records and context apply."],
      ["What does “your system” mean?", "Your company receives standard modules and features, and can develop custom ones that belong only to you.", "Your system begins with a standard foundation of modules and features available to every customer. When the company needs something specific, Dev One can build a custom module, workflow, or capability for that company’s installation. Those custom capabilities belong only to that company, and the company decides how its system evolves."],
      ["Is it ready to use?", "Yes. It is still in its early stages, but it already offers many useful capabilities—and more are added regularly.", "The system is ready for real company workflows today and continues to expand. Regular releases add standard features and improvements. Each company’s priorities can guide the custom modules, workflows, and capabilities Dev One builds next."]
    ]
  },
  closing: { title: ["Your company.", "One system.", "CompanyONE"], body: "A system that becomes more yours with every improvement.", note: "In active development. Built with real small businesses.", top: "Back to top" },
};
