  hero: { intro: "Hecho para tu negocio", title: ["Tu empresa.", "Un solo sistema."], body: "Tu propia computadora. Un sistema que puedes adaptar. Agentes privados en tu equipo.", scene: "Ilustración 3D de CompanyONE: una computadora de la empresa sostiene módulos de negocio conectados, con Agent One y Dev One a su lado.", tabs: ["Tu computadora", "Tu sistema", "Tu equipo"], descriptions: ["La base es tuya. CompanyONE funciona en hardware que tu empresa controla.", "Empieza con módulos conectados. Trae tus datos. Adapta cada flujo a tu negocio.", "Agent One hace el trabajo. Dev One hace evolucionar el sistema. Ambos trabajan con tu equipo."], pause: "Pausar animación", play: "Reproducir animación" },
